// Ingest payload from Devyx website /api/chat
const body = $input.first().json.body || $input.first().json;

const sessionId = body.sessionId || `session_${Date.now()}`;
const userMessage = (body.message || '').trim();
let language = (body.language || 'auto').toLowerCase();
const currentPage = body.currentPage || '/';

// Darija patterns (Arabizi digits/vocabulary or Arabic script dialect)
const arabiziPattern = /\b(bghit|khoya|kidayr|chhal|ch7al|salam|fin|3afak|dyal|doka|dorka|lazem|saguem|khedma|wach|chno|fash|krite|tomobil|sachi|trisiti|bezzaf|kayen|chta|we9t|9bel|9alli|chouf|hada|hadi|mzyan|mli7|chwiya|3afak|t3ich|n9der|kifech|kifach|rani|rakom)\b/i;
const arabiziDigits = /\b[a-zA-Z]*[23579][a-zA-Z]*\b/;
const arabicDarijaPattern = /(باش|ديال|بغيت|شنو|واش|شحال|فين|عافاك|زوين|بزاف|مزيان|دابا|كاين|كنديرو|كنقدرو|سوءال|ساهل|خدمة|دارجة|حنا|نتوما|هاد|دير)/;

const isDarija = language === 'darija' || language === 'ar-ma' || arabiziPattern.test(userMessage) || arabiziDigits.test(userMessage) || arabicDarijaPattern.test(userMessage);

// If language was "auto", detect effectively
if (language === 'auto') {
  if (isDarija) {
    language = 'darija';
  } else if (/[\u0600-\u06FF]/.test(userMessage)) {
    language = 'ar';
  } else if (/[éèêëàâôûùçîï]/i.test(userMessage) || /\b(bonjour|salut|combien|coute|coûte|prix|projet|site|vous|nous|pour|faire|créer)\b/i.test(userMessage)) {
    language = 'fr';
  } else {
    language = 'en';
  }
}

return {
  json: {
    sessionId,
    userMessage,
    language,
    currentPage,
    isDarija,
    // Context passed to Stage 1 Devyx Technical Assistant
    assistantInputText: userMessage
  }
};

