// Sanitize Output Node (Exact Perfected Regex from Darija Benchmark Suite)
for (const item of $input.all()) {
    if (item.json && typeof item.json.text === 'string') {
        let t = item.json.text;

        // 1. Script purity: Eliminate any hybrid or stray Arabic characters
        t = t.replace(/nرحب\s*بيك/gi, 'nre7eb bik');
        t = t.replace(/رحب\s*بيك/gi, 're7eb bik');
        t = t.replace(/[\u0600-\u06FF]/g, '');

        // 2. Strict '9' for Qaf
        t = t.replace(/\bqbel\b/gi, '9bel');
        t = t.replace(/\bqalli\b/gi, '9alli');
        t = t.replace(/\bqrib\b/gi, '9rib');
        t = t.replace(/\bwaqt\b/gi, 'we9t');
        t = t.replace(/\blwaqt\b/gi, 'lwe9t');
        t = t.replace(/\byetqta3\b/gi, 'yet9ta3');
        t = t.replace(/\btqta3et\b/gi, 't9at3et');
        t = t.replace(/\bdeqiq[ae]\b/gi, 'd9i9a');
        t = t.replace(/\bdqiq[ae]\b/gi, 'd9i9a');

        // 3. Dialect leaks purge
        t = t.replace(/\b7it\b/gi, '3la khater');
        t = t.replace(/\bdaba\b/gi, 'doka');
        t = t.replace(/\bghadi\b/gi, 'ra7');
        t = t.replace(/\bdyalna\b/gi, 'ta3na');
        t = t.replace(/\bdyal\b/gi, 'ta3');

        item.json.sanitizedText = t.trim();
        item.json.text = t.trim();
    }
}
return $input.all();

// Prepare final payload for website HTTP response
const prepContext = $('Context & Language Detector').first().json;
const isDarija = prepContext.isDarija;

let finalReply = '';

if (isDarija) {
  const sanitizeNode = $('Sanitize Output').first();
  finalReply = sanitizeNode?.json?.text || sanitizeNode?.json?.sanitizedText || '';
} else {
  const assistantNode = $('Devyx Assistant Agent').first();
  finalReply = assistantNode?.json?.text || assistantNode?.json?.response || '';
}

if (!finalReply || finalReply.trim() === '') {
  finalReply = isDarija
    ? "Salam! Rani hna bach n3awnek f kol ma ykhess les projets ta3 web, mobile w automations n8n f Devyx. T9der tcontactina direct f [WhatsApp](https://wa.me/213000000000) wela f [Page Contact](/contact)."
    : "Welcome to Devyx! Our engineering team specializes in high-throughput web platforms, cross-platform mobile apps, and self-hosted n8n automation pipelines. Connect with our engineering director directly via [WhatsApp](https://wa.me/213000000000) or our [Contact Page](/contact).";
}

return {
  json: {
    reply: finalReply,
    sessionId: prepContext.sessionId,
    language: isDarija ? 'darija' : prepContext.language,
    translated: isDarija,
    status: 'success'
  }
};
